solution.solution.py:
DIGITS = "0123456789ABCDEF"

def to_hex(n):
    if n == 0:
        return "0"
    out = ""
    while n > 0:
        out = DIGITS[n % 16] + out
        n //= 16
    return out

def from_hex(text):
    text = text.upper()
    if text.startswith("0X"):
        text = text[2:]
    value = 0
    for ch in text:
        value = value * 16 + DIGITS.index(ch)
    return value

def binary_to_hex(bits):
    while len(bits) % 4 != 0:
        bits = "0" + bits
    out = ""
    for i in range(0, len(bits), 4):
        group = bits[i:i + 4]
        value = 0
        for ch in group:
            value = value * 2 + (1 if ch == "1" else 0)
        out += DIGITS[value]
    return out
